insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-165', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'Typical industrial Haber conditions taught at Intermediate level are about', '["200 atm, 450 °C, finely divided iron","1 atm, 25 °C, no catalyst","1000 atm, 1000 °C, platinum gauze","0.1 atm, 800 °C, nickel"]'::jsonb, 0, 'High pressure favours NH3; a compromise temperature near 450 °C with an Fe catalyst gives a usable rate.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
