insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-167', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'A very high temperature is avoided in Haber manufacture even though the rate would rise, because', '["the equilibrium yield of ammonia falls","iron melts at 100 °C","Kp becomes infinite","hydrogen liquefies"]'::jsonb, 0, 'The forward Haber reaction is exothermic, so K falls as T rises and less NH3 is present at equilibrium.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
