insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-170', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For the dissociation of PCl5, the degree of dissociation $\alpha$ falls when the pressure is raised because', '["the product side has more moles of gas","Kp increases with P","the reaction is endothermic","PCl5 is a solid"]'::jsonb, 0, 'Le Chatelier: extra pressure is relieved by forming fewer gas molecules, i.e. undissociated PCl5.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
