insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-171', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'A compromise temperature is chosen for Haber synthesis because', '["low T favours yield but makes the reaction slow","high T always maximises both yield and rate","temperature does not affect ammonia","the catalyst works only at 0 °C"]'::jsonb, 0, 'K is larger at low T (exothermic) but molecules react slowly; ~450 °C with a catalyst is the industrial compromise.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
